 async function runCommand(input,form){const dialog=$('#dialog'),key=JSON.stringify(input);if(!dialog._pending||dialog._pending.key!==key)dialog._pending={key,input:{...input,expectedRevision:state.revision,requestId:VenuesAPI.requestId()}};const result=await VenuesAPI.command(dialog._pending.input);dialog._pending=null;return result;}
 function applyResult(result){if(result.revision!==undefined)state.revision=Math.max(state.revision,result.revision);for(const row of result.occurrences||[])state.occurrences.set(row.id,row);for(const row of result.transfers||[])state.transfers.set(row.id,row);for(const row of result.venues||[]){const i=state.venues.findIndex(v=>v.id===row.id);if(i<0)state.venues.push(row);else state.venues[i]=row;}if(result.closures){const rows=new Map(state.closures.map(c=>[c.id,c]));for(const c of result.closures)rows.set(c.id,c);state.closures=[...rows.values()];}if(result.permissions)state.permissions=result.permissions;if(result.source)state.source=result.source;state.admin=null;if(result.delivery?.failed||result.delivery?.uncertain)setStatus((result.message||'Saved.')+' Some notices need administrator attention.','warning');}
 function openOccupied(venueId,p,o){if(o.kind==='closed')return;if(o.kind!=='timetable'&&o.record?.ownerId===state.actor.id){manageBooking(o.record);return;}const v=venue(venueId),booking=o.kind==='timetable'?null:o.record;let body='<p><strong>'+esc(v.unit)+' · '+esc(v.name)+'</strong></p><p>'+esc(dateLabel(state.date))+' · '+esc(p.label)+' '+minute(p.start)+'–'+minute(p.end)+'</p><p>'+esc(o.label)+'</p>'+(booking?'<p class="note">'+esc(booking.note||'No preparation request.')+'</p>':'<p class="helper">The assigned room owners or Venues administrators can review a timetable transfer.</p>')+'<div class="field"><label for="transferNote">Reason for transfer</label><textarea id="transferNote" maxlength="2000" rows="3"></textarea></div>';
  showDialog('Occupied venue',body,'Request transfer',async form=>{const input={operation:'requestTransfer',kind:booking?'booking':'timetable',venueId,date:state.date,periodIds:booking?.periodIds||[p.id],note:$('#transferNote',form).value,...(booking?{bookingId:booking.id,bookingRevision:booking.revision}:{})};const result=await runCommand(input,form);applyResult(result);setStatus(result.message||'Transfer requested. The existing booking remains reserved.','success');});
 }
 function groupPeriods(row){const selected=(row.periodIds||[]).map(period).filter(Boolean).sort((a,b)=>a.start-b.start),groups=[];for(const p of selected){const last=groups.at(-1);if(last&&last.at(-1).end===p.start)last.push(p);else groups.push([p]);}return groups.length?groups:[(row.intervals||[]).map((i,index)=>({id:'i'+index,label:'Booking',...i}))];}
