 function renderMine(){const todayValue=today(),rows=[...state.occurrences.values()].filter(o=>o.ownerId===state.actor.id||o.requesterId===state.actor.id).filter(o=>state.mineFilter==='pending'?o.status==='pending':state.mineFilter==='past'?o.date<todayValue:state.mineFilter==='history'?['cancelled','rejected','displaced'].includes(o.status):o.date>=todayValue&&active(o)).sort((a,b)=>a.date.localeCompare(b.date)||a.intervals[0].start-b.intervals[0].start);
  $('#main').innerHTML='<section class="card"><div class="section-heading"><div><h2>My bookings</h2><p>Manage one booking or the remaining dates in a series.</p></div></div><div class="toolbar"><div class="field"><label for="mineFilter">Show</label><select id="mineFilter" name="mineFilter">'+[['upcoming','Upcoming'],['pending','Awaiting decisions'],['past','Past'],['history','Cancelled / displaced']].map(([v,t])=>'<option value="'+v+'" '+(v===state.mineFilter?'selected':'')+'>'+t+'</option>').join('')+'</select></div><div class="field"><label for="mineFrom">From</label><input type="date" id="mineFrom" name="mineFrom" value="'+esc(state.mineFrom)+'"></div><div class="field"><label for="mineTo">To</label><input type="date" id="mineTo" name="mineTo" value="'+esc(state.mineTo||state.manifest?.to||todayValue)+'"></div><button data-load-mine type="button">Load bookings</button></div><div class="list">'+(rows.slice(0,state.listLimits.mine).map(o=>rowHTML(o,o.ownerId===state.actor.id)).join('')||'<div class="empty">No bookings in this view.</div>')+'</div>'+moreList('mine',rows.length)+'<section class="transfer-list"><h3>Transfer requests</h3>'+transferHTML([...state.transfers.values()].filter(t=>t.requesterId===state.actor.id||t.originalOwnerId===state.actor.id))+'</section></section>';
  $('[name="mineFilter"]').onchange=e=>{state.mineFilter=e.target.value;renderMine();};$('[name="mineFrom"]').onchange=e=>state.mineFrom=e.target.value;$('[name="mineTo"]').onchange=e=>state.mineTo=e.target.value;$('[data-load-mine]').onclick=async()=>{try{safeDates(state.mineFrom,state.mineTo||(state.manifest?.to||today()));await loadBookings(state.mineFrom,state.mineTo||(state.manifest?.to||today()),{mine:true});}catch(e){showError(e);}};wireBookingActions();wireTransferActions();wireMore();
 }
 function renderDashboard(){const found=state.venues.filter(v=>matches(v,state.roomSearch)),selection=new Set(state.roomIds),rows=[...state.occurrences.values()].filter(o=>selection.has(o.venueId)&&o.date>=state.dashboardFrom&&o.date<=state.dashboardTo&&(state.dashboardHistory||active(o))).sort((a,b)=>a.date.localeCompare(b.date)||String(venue(a.venueId)?.unit).localeCompare(String(venue(b.venueId)?.unit))||a.intervals[0].start-b.intervals[0].start);
  $('#main').innerHTML='<section class="card"><div class="section-heading"><div><h2>Room dashboard</h2><p>Bookings and preparation requests for your selected rooms.</p></div><button type="button" data-copy-dashboard>Copy dashboard link</button></div><div class="toolbar"><div class="field grow"><label for="roomSearch">Find rooms</label><div class="search-row actions"><input id="roomSearch" data-room-search type="search" value="'+esc(state.roomSearch)+'" placeholder="Unit or description"><button type="button" data-clear-room-search '+(!state.roomSearch?'hidden':'')+'>Clear search</button></div></div><div class="field"><label for="dashboardFrom">From</label><input id="dashboardFrom" name="dashboardFrom" type="date" value="'+esc(state.dashboardFrom)+'"></div><div class="field"><label for="dashboardTo">To</label><input id="dashboardTo" name="dashboardTo" type="date" value="'+esc(state.dashboardTo)+'"></div><button type="button" class="primary" data-load-dashboard>Show bookings</button></div><div class="actions"><button type="button" class="small" data-select-filtered>Select all filtered</button><button type="button" class="small" data-clear-rooms>Clear selection</button><span class="helper">'+selection.size+' rooms selected</span></div><div class="room-select" data-room-options>'+found.map(v=>'<label class="room-option"><input type="checkbox" data-dashboard-room="'+esc(v.id)+'" '+(selection.has(v.id)?'checked':'')+'><span><strong>'+esc(v.unit)+'</strong><small>'+esc(v.name)+'</small></span></label>').join('')+'</div><div class="chips">'+state.roomIds.map(id=>'<span class="chip">'+esc(venue(id)?.unit||id)+'<button type="button" data-remove-room="'+esc(id)+'" aria-label="Remove '+esc(venue(id)?.unit||id)+'">×</button></span>').join('')+'</div><label class="inline-check"><input type="checkbox" data-history '+(state.dashboardHistory?'checked':'')+'>Include cancelled, rejected and displaced bookings</label></section><section class="card"><div class="list">'+(rows.slice(0,state.listLimits.dashboard).map(o=>rowHTML(o,manager(o.venueId))).join('')||'<div class="empty">'+(selection.size?'No ad hoc bookings in the selected rooms and dates.':'Select rooms to view their bookings.')+'</div>')+'</div>'+moreList('dashboard',rows.length)+'<div data-timetable-agenda></div></section>';
  $('[data-room-search]').oninput=e=>{const start=e.target.selectionStart;state.roomSearch=e.target.value;renderDashboard();const next=$('[data-room-search]');next.focus();next.setSelectionRange(start,start);};$('[data-clear-room-search]').onclick=()=>{state.roomSearch='';renderDashboard();$('[data-room-search]').focus();};$('[name="dashboardFrom"]').onchange=e=>state.dashboardFrom=e.target.value;$('[name="dashboardTo"]').onchange=e=>state.dashboardTo=e.target.value;
  $$('[data-dashboard-room]').forEach(c=>c.onchange=()=>{state.roomIds=c.checked?[...new Set([...state.roomIds,c.dataset.dashboardRoom])]:state.roomIds.filter(id=>id!==c.dataset.dashboardRoom);changeURL();});$('[data-select-filtered]').onclick=()=>{state.roomIds=[...new Set([...state.roomIds,...found.map(v=>v.id)])];changeURL();renderDashboard();};$('[data-clear-rooms]').onclick=()=>{state.roomIds=[];changeURL();renderDashboard();};$$('[data-remove-room]').forEach(b=>b.onclick=()=>{state.roomIds=state.roomIds.filter(id=>id!==b.dataset.removeRoom);changeURL();renderDashboard();});$('[data-history]').onchange=e=>{state.dashboardHistory=e.target.checked;renderDashboard();};
  $('[data-load-dashboard]').onclick=async()=>{try{safeDates(state.dashboardFrom,state.dashboardTo);changeURL();await loadBookings(state.dashboardFrom,state.dashboardTo,{venueIds:state.roomIds});}catch(e){showError(e);}};$('[data-copy-dashboard]').onclick=async()=>{changeURL();try{await navigator.clipboard.writeText(location.href);setStatus('Dashboard link copied. Staff must sign in to open it.','success');}catch{setStatus('Copy this dashboard address from your browser.','warning');}};wireBookingActions();renderTimetableAgenda();wireMore();
 }
 function renderTimetableAgenda(){const target=$('[data-timetable-agenda]');if(!target||!state.roomIds.length)return;let dates;try{dates=safeDates(state.dashboardFrom,state.dashboardTo);}catch{return;}let html='';for(const date of dates){if(!knownDate(date)){html+='<p class="status warning">'+esc(dateLabel(date))+': timetable coverage unavailable.</p>';continue;}const entries=timetable(date).filter(t=>state.roomIds.includes(t.venueId));for(const row of entries)html+='<article class="booking-row"><div><strong>'+esc(venue(row.venueId)?.unit)+'</strong><p class="row-meta">'+esc(dateLabel(date))+'</p></div><div class="period-list">'+periodsFor(date).filter(p=>overlaps(p,row)).map(p=>'<span>'+esc(p.label)+' '+minute(p.start)+'–'+minute(p.end)+'</span>').join('')+'</div><div class="booking-content">'+esc(timetableLabel(row))+'</div></article>'; }if(html)target.innerHTML='<h3 class="agenda-heading">Timetable reservations</h3><div class="list">'+html+'</div>';
 }
 function moreList(view,count){return '<div class="actions"><p class="helper">Showing '+Math.min(count,state.listLimits[view])+' of '+count+' loaded bookings</p>'+(count>state.listLimits[view]?'<button type="button" data-show-more="'+view+'">Show 50 more</button>':'')+'</div>'; }
